  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(0, 212, 255, 0.1) !important;
  margin-top: 8px !important;
}

/* --- 2. 演算核心（模型）名称 (样式保持不变) --- */
